import sys
from abc import ABC, abstractmethod

class BankAccount(ABC):
    def __init__(self, balance: int):
        self.balance = balance

    @abstractmethod
    def deposit(self, amount: int):
        pass

    @abstractmethod
    def withdraw(self, amount: int):
        pass

class SavingsAccount(BankAccount):
    MIN_BAL = 1000

    def deposit(self, amount: int):
        self.balance += amount
        return True

    def withdraw(self, amount: int):
        if self.balance - amount < self.MIN_BAL:
            return False
        self.balance -= amount
        return True

class CurrentAccount(BankAccount):
    def deposit(self, amount: int):
        self.balance += amount
        return True

    def withdraw(self, amount: int):
        self.balance -= amount
        return True

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    if len(data) < 4:
        return
    account_type = data[0].lower()
    try:
        initial_balance = int(data[1])
    except ValueError:
        initial_balance = 0
    transaction_type = data[2].lower()
    try:
        transaction_amount = int(data[3])
    except ValueError:
        transaction_amount = 0

    if account_type == 'savings':
        account = SavingsAccount(initial_balance)
    else:
        account = CurrentAccount(initial_balance)

    if transaction_type == 'deposit':
        account.deposit(transaction_amount)
        sys.stdout.write(str(account.balance))
    elif transaction_type == 'withdraw':
        if not account.withdraw(transaction_amount):
            sys.stdout.write('Insufficient balance')
        else:
            sys.stdout.write(str(account.balance))

if __name__ == "__main__":
    main()
